_BASE_INT = {"A": 0, "C": 1, "G": 2, "T": 3}


def codon_to_id(codon: str) -> int:
    """Map a 3-letter codon to an integer in [0, 64). Returns 64 if any base is
    not ACGT.
    """
    try:
        return 16 * _BASE_INT[codon[0]] + 4 * _BASE_INT[codon[1]] + _BASE_INT[codon[2]]
    except KeyError:
        return 64


_BASE_TABLE = np.full(256, -1, dtype=np.int8)
for _ch, _v in [("A", 0), ("a", 0), ("C", 1), ("c", 1),
                 ("G", 2), ("g", 2), ("T", 3), ("t", 3)]:
    _BASE_TABLE[ord(_ch)] = _v

_COMPLEMENT = np.array([3, 2, 1, 0], dtype=np.int32)


def encode_triplets(seq: str) -> Tuple[np.ndarray, np.ndarray]:
    """Compute per-position triplet IDs for both strands from the forward
    sequence.

    Returns
    -------
    triplet_plus : (L,) int64
        ``S[j:j+3]`` encoded as an integer in [0, 64). Last 2 positions get 64.
    triplet_minus : (L,) int64
        ``RC(S[j-2:j+1])`` encoded (i.e. the codon read on the − strand that
        spans forward positions ``[j-2, j+1)``, oriented so that its first base
        is at forward position ``j``). First 2 positions get 64.
    """
    si = _BASE_TABLE[np.frombuffer(seq.encode("ascii"), dtype=np.uint8)].astype(np.int32)
    L = si.shape[0]
    invalid = si < 0
    t_plus = np.full(L, 64, dtype=np.int64)
    t_minus = np.full(L, 64, dtype=np.int64)
    if L >= 3:
        inv3p = invalid[:L - 2] | invalid[1:L - 1] | invalid[2:L]
        valsp = 16 * si[:L - 2] + 4 * si[1:L - 1] + si[2:L]
        okp = ~inv3p
        idxp = np.nonzero(okp)[0]
        t_plus[idxp] = valsp[okp]

        comp = np.where(si >= 0, 3 - si, -1).astype(np.int32)
        inv3m = invalid[2:] | invalid[1:-1] | invalid[:-2]
        valsm = 16 * comp[2:] + 4 * comp[1:-1] + comp[:-2]
        okm = ~inv3m
        idxm = np.nonzero(okm)[0] + 2
        t_minus[idxm] = valsm[okm]
    return t_plus, t_minus


