_MINUS_LOG = math.log(1e-30)
_NEG_INF = -1e30


def _parallel_fb_chunk_size() -> int:
    text = os.environ.get("HMM_PARALLEL_CHUNK", "0").strip()
    if not text:
        return 0
    try:
        return max(0, int(text))
    except ValueError:
        raise ValueError(f"HMM_PARALLEL_CHUNK must be an integer, got {text!r}")


def _local_segment_tables(
    segment_emit: torch.Tensor,
    log_trans: torch.Tensor,
    *,
    first_segment: torch.Tensor,
) -> Tuple[torch.Tensor, torch.Tensor]:
    """Compute all start-state -> current-state tables for same-length segments.

    ``segment_emit`` is ``(B, N, M, S)``. The returned local table is
    ``(B, N, M, S, S)`` where the last two axes are
    ``(state before segment, current state)``. Segment 0 uses an identity
    start-state relation so combining with ``log_init`` reproduces the standard
    ``alpha[:, 0] = log_init + emit[:, 0]`` initialization.
    """
    B, N, M, S = segment_emit.shape
    log_eye = torch.full((S, S), _NEG_INF, device=segment_emit.device, dtype=segment_emit.dtype)
    log_eye.fill_diagonal_(0.0)
    first0 = log_eye.view(1, 1, S, S) + segment_emit[:, :, 0].unsqueeze(-2)
    other0 = log_trans.view(1, 1, S, S) + segment_emit[:, :, 0].unsqueeze(-2)
    first_mask = first_segment.to(device=segment_emit.device).view(1, N, 1, 1)
    cur = torch.where(first_mask, first0, other0)
    tables = [cur]
    for r in range(1, M):
        cur = torch.logsumexp(cur.unsqueeze(-1) + log_trans.view(1, 1, 1, S, S), dim=-2)
        cur = cur + segment_emit[:, :, r].unsqueeze(-2)
        tables.append(cur)
    local = torch.stack(tables, dim=2)
    return local, local[:, :, -1]


def _forward_backward_log_emit_segmented(
    log_emit: torch.Tensor,
    log_trans: torch.Tensor,
    log_init: torch.Tensor,
    chunk_size: int,
) -> Tuple[torch.Tensor, torch.Tensor, torch.Tensor, torch.Tensor]:
    """Exact forward-backward with local segment tables batched across chunks.

    This follows the two-stage Tiberius idea: local dynamic programs are computed
    for many chunks in parallel, then chunk boundaries are combined sequentially.
    It preserves the same outputs as the sequential implementation while
    reducing Python loop depth from ``L`` to roughly ``chunk_size + L/chunk``.
    """
    B, L, S = log_emit.shape
    if chunk_size <= 0 or chunk_size >= L:
        return _forward_backward_log_emit_sequential(log_emit, log_trans, log_init)

    starts = list(range(0, L, chunk_size))
    lengths = [min(chunk_size, L - s) for s in starts]
    nseg = len(starts)
    local_by_seg = [None] * nseg
    transfer_by_seg = [None] * nseg
    emit_by_seg = [None] * nseg

    for seg_len in sorted(set(lengths), reverse=True):
        idxs = [i for i, m in enumerate(lengths) if m == seg_len]
        seg_emit = torch.stack([log_emit[:, starts[i] : starts[i] + seg_len] for i in idxs], dim=1)
        first_flags = torch.tensor([i == 0 for i in idxs], device=log_emit.device, dtype=torch.bool)
        local, transfer = _local_segment_tables(seg_emit, log_trans, first_segment=first_flags)
        for pos, seg_idx in enumerate(idxs):
            local_by_seg[seg_idx] = local[:, pos]
            transfer_by_seg[seg_idx] = transfer[:, pos]
            emit_by_seg[seg_idx] = seg_emit[:, pos]

    alpha_parts = []
    boundary = log_init.view(1, S).expand(B, S)
    for local in local_by_seg:
        alpha_seg = torch.logsumexp(boundary[:, None, :, None] + local, dim=-2)
        alpha_parts.append(alpha_seg)
        boundary = alpha_seg[:, -1]
    log_alpha = torch.cat(alpha_parts, dim=1)
    log_z = torch.logsumexp(log_alpha[:, -1], dim=-1)

    beta_end_by_seg = [None] * nseg
    beta_after = torch.zeros((B, S), device=log_emit.device, dtype=log_emit.dtype)
    for seg_idx in range(nseg - 1, -1, -1):
        beta_end_by_seg[seg_idx] = beta_after
        if seg_idx > 0:
            transfer = transfer_by_seg[seg_idx]
            beta_after = torch.logsumexp(transfer + beta_after[:, None, :], dim=-1)

    beta_parts = [None] * nseg
    for seg_idx in range(nseg - 1, -1, -1):
        emit = emit_by_seg[seg_idx]
        M = emit.shape[1]
        beta = torch.empty((B, M, S), device=log_emit.device, dtype=log_emit.dtype)
        beta[:, -1] = beta_end_by_seg[seg_idx]
        for r in range(M - 2, -1, -1):
            nxt = emit[:, r + 1].unsqueeze(1) + beta[:, r + 1].unsqueeze(1)
            beta[:, r] = torch.logsumexp(log_trans.view(1, S, S) + nxt, dim=-1)
        beta_parts[seg_idx] = beta
    log_beta = torch.cat(beta_parts, dim=1)

    log_gamma = log_alpha + log_beta - log_z.view(B, 1, 1)
    gamma = torch.exp(log_gamma.clamp(min=-80.0, max=0.0))
    gamma = gamma / gamma.sum(dim=-1, keepdim=True).clamp_min(1e-12)
    return gamma, log_z, log_alpha, log_beta


def _forward_backward_log_emit_sequential(
    log_emit: torch.Tensor,
    log_trans: torch.Tensor,
    log_init: torch.Tensor,
) -> Tuple[torch.Tensor, torch.Tensor, torch.Tensor, torch.Tensor]:
    B, L, S = log_emit.shape
    tr_b = log_trans.unsqueeze(0)

    log_alpha = torch.empty_like(log_emit)
    log_alpha[:, 0] = log_init.unsqueeze(0) + log_emit[:, 0]
    for t in range(1, L):
        log_alpha[:, t] = torch.logsumexp(
            log_alpha[:, t - 1].unsqueeze(-1) + tr_b,
            dim=-2,
        ) + log_emit[:, t]

    log_beta = torch.empty_like(log_emit)
    log_beta[:, -1] = 0.0
    for t in range(L - 2, -1, -1):
        nxt = log_emit[:, t + 1].unsqueeze(1) + log_beta[:, t + 1].unsqueeze(1)
        log_beta[:, t] = torch.logsumexp(tr_b + nxt, dim=-1)

    log_z = torch.logsumexp(log_alpha[:, -1], dim=-1)
    log_gamma = log_alpha + log_beta - log_z.view(B, 1, 1)
    gamma = torch.exp(log_gamma.clamp(min=-80.0, max=0.0))
    gamma = gamma / gamma.sum(dim=-1, keepdim=True).clamp_min(1e-12)
    return gamma, log_z, log_alpha, log_beta


def _forward_backward_log_emit(
    log_emit: torch.Tensor,
    log_trans: torch.Tensor,
    log_init: torch.Tensor,
) -> Tuple[torch.Tensor, torch.Tensor, torch.Tensor, torch.Tensor]:
    """Run log-space forward-backward on emissions.

    Shapes: ``log_emit`` is ``(L, S)`` or ``(B, L, S)``, ``log_trans`` is
    ``(S, S)``, and ``log_init`` is ``(S,)``. Returns ``gamma`` posterior
    probabilities ``(B, L, S)``, marginal log-likelihood ``log_z`` ``(B,)``,
    and the ``log_alpha`` / ``log_beta`` tables ``(B, L, S)``.
    """
    if log_emit.dim() == 2:
        log_emit = log_emit.unsqueeze(0)
    if log_emit.dim() != 3:
        raise ValueError(f"log_emit must be (L,S) or (B,L,S), got {tuple(log_emit.shape)}")
    B, L, S = log_emit.shape
    if log_trans.shape != (S, S):
        raise ValueError(f"log_trans must be {(S, S)}, got {tuple(log_trans.shape)}")
    if log_init.shape != (S,):
        raise ValueError(f"log_init must be {(S,)}, got {tuple(log_init.shape)}")

    log_trans = log_trans.to(device=log_emit.device, dtype=log_emit.dtype)
    log_init = log_init.to(device=log_emit.device, dtype=log_emit.dtype)
    chunk_size = _parallel_fb_chunk_size()
    if chunk_size > 0:
        return _forward_backward_log_emit_segmented(log_emit, log_trans, log_init, chunk_size)
    return _forward_backward_log_emit_sequential(log_emit, log_trans, log_init)


def _log_c_row_start_canonical(
    start_codon_logits: torch.Tensor,
    start_ids: torch.Tensor,
    device: torch.device,
    dtype: torch.dtype,
) -> torch.Tensor:
    """START0 row: softmax over the first ``N_START_EMITTING`` starts; rest −inf."""
    row = torch.full((65,), _NEG_INF, device=device, dtype=dtype)
    k = max(1, min(int(N_START_EMITTING), int(start_ids.numel())))
    sk = F.log_softmax(start_codon_logits[:k], dim=-1)
    for i in range(k):
        row[start_ids[i]] = sk[i]
    row[64] = 0.0
    return row


def _prob_to_logit(p: float) -> float:
    p = min(max(p, 1e-6), 1 - 1e-6)
    return math.log(p / (1 - p))


def strand_hmm_nn_channels(mode: str | None = None) -> Tuple[int, ...]:
    """State→NN-channel mapping for the 10-state strand HMM.

    ``triple`` supervises all three START/STOP codon bases as boundary labels.
    ``edge`` supervises only START0 and STOP2 as boundary labels; the other two
    codon bases emit their frame channels while codon weights still live on
    START0/STOP0 in ``log_c_table``.
    """
    m = (mode or get_boundary_label_mode()).strip().lower()
    if m == "triple":
        return ProkaryoticStrandHMM.CANONICAL_CHANNELS_TRIPLE
    if m == "edge":
        return ProkaryoticStrandHMM.CANONICAL_CHANNELS_EDGE
    raise ValueError(f"unknown boundary label mode: {m!r}")


def joint_hmm_nn_channels(mode: str | None = None) -> Tuple[int, ...]:
    """State→NN-channel mapping for the 19-state joint HMM."""
    m = (mode or get_boundary_label_mode()).strip().lower()
    if m == "triple":
        return ProkaryoticJointHMM.NN_CHANNEL_TRIPLE
    if m == "edge":
        return ProkaryoticJointHMM.NN_CHANNEL_EDGE
    raise ValueError(f"unknown boundary label mode: {m!r}")


def _combine_log_emission(
    log_b: torch.Tensor,
    log_c: torch.Tensor,
    start_state_ids: Tuple[int, ...],
    start_emission_scale: float,
) -> torch.Tensor:
    """``log_emit = log_b + log_c``, with optional ``scale * log_b`` on START states only."""
    if start_emission_scale == 1.0:
        return log_b + log_c
    out = log_b + log_c
    for idx in start_state_ids:
        out[..., idx] = start_emission_scale * log_b[..., idx] + log_c[..., idx]
    return out


class ProkaryoticStrandHMM(nn.Module):
    """Single-strand HMM (Strategy A).

    Parameters
    ----------
    stats : dict
        Output of ``measure_stats.py`` (loaded from JSON).
    alpha : float
        NN-smoothing weight for the ``b`` factor; 0.01 is the Tiberius default.
    start_emission_scale : float
        Decode-time multiplier on ``log b`` for START states only:
        ``log_emit_START = start_emission_scale * log_b + log_c`` (default 1).
    trainable : bool
        Whether HMM parameters require grad. Phase 1 uses ``False``;
        Phase 2/3 use ``True``.
    """

    NUM_STATES = 12
    START_STATE_IDS = (1, 2, 3, 10, 11)
    STATE_NAMES = (
        "IGR", "START0", "START1", "START2",
        "CDS0", "CDS1", "CDS2", "STOP0", "STOP1", "STOP2",
        "START_OVERLAP_4", "START_OVERLAP_7",
    )
    IGR = 0
    START0, START1, START2 = 1, 2, 3
    CDS0, CDS1, CDS2 = 4, 5, 6
    STOP0, STOP1, STOP2 = 7, 8, 9
    START_OVERLAP_4, START_OVERLAP_7 = 10, 11

    # Canonical channel for each state into the (L, 6) strand slice.
    # Slice layout: [IGR, Frame0, Frame1, Frame2, START, STOP].
    CANONICAL_CHANNELS_TRIPLE = (0, 4, 4, 4, 1, 2, 3, 5, 5, 5, 4, 4)
    CANONICAL_CHANNELS_EDGE = (0, 4, 2, 3, 1, 2, 3, 1, 2, 5, 4, 4)

    def __init__(
        self,
        stats: Dict,
        alpha: float = 0.01,
        trainable: bool = False,
        start_emission_scale: float = 1.0,
        overlap_probs: Optional[Dict[str, float]] = None,
    ):
        super().__init__()
        self.alpha = float(alpha)
        self.start_emission_scale = float(start_emission_scale)
        overlap_probs = overlap_probs or load_overlap_transition_probs()

        d = stats["derived"]
        self.igr_exit_logit = nn.Parameter(
            torch.tensor(_prob_to_logit(d["p_exit_igr"]), dtype=torch.float32),
            requires_grad=trainable,
        )
        self.cds_exit_logit = nn.Parameter(
            torch.tensor(_prob_to_logit(d["p_exit_cds"]), dtype=torch.float32),
            requires_grad=trainable,
        )

        sfreqs = stats.get("start_codon_freqs") or ECOLI_START_CODON_FREQS
        s_init = torch.tensor(
            [max(sfreqs.get(c, 0.0), 1e-6) for c in START_CODONS_10],
            dtype=torch.float32,
        )
        self.start_codon_logits = nn.Parameter(
            torch.log(s_init), requires_grad=trainable,
        )
        zfreqs = stats.get("stop_codon_freqs") or ECOLI_STOP_CODON_FREQS
        z_init = torch.tensor(
            [max(zfreqs.get(c, 0.0), 1e-6) for c in STOP_CODONS],
            dtype=torch.float32,
        )
        self.stop_codon_logits = nn.Parameter(
            torch.log(z_init), requires_grad=trainable,
        )

        start_ids = torch.tensor(
            [codon_to_id(c) for c in START_CODONS_10], dtype=torch.long,
        )
        stop_ids = torch.tensor(
            [codon_to_id(c) for c in STOP_CODONS], dtype=torch.long,
        )
        sense_ids = torch.tensor(
            sorted(set(range(64)) - set(stop_ids.tolist())), dtype=torch.long,
        )
        self.register_buffer("start_ids", start_ids)
        self.register_buffer("stop_ids", stop_ids)
        self.register_buffer("sense_ids", sense_ids)
        self.register_buffer(
            "canonical_channels",
            torch.tensor(strand_hmm_nn_channels(), dtype=torch.long),
            persistent=False,
        )
        self.register_buffer(
            "_p_overlap_1",
            torch.tensor(float(overlap_probs["p_overlap_1"]), dtype=torch.float32),
            persistent=False,
        )
        self.register_buffer(
            "_p_overlap_4",
            torch.tensor(float(overlap_probs["p_overlap_4"]), dtype=torch.float32),
            persistent=False,
        )
        self.register_buffer(
            "_p_overlap_7",
            torch.tensor(float(overlap_probs["p_overlap_7"]), dtype=torch.float32),
            persistent=False,
        )

    # ─── parameter access ──────────────────────────────────────────────

    @property
    def p_loop_igr(self) -> float:
        return float(1.0 - torch.sigmoid(self.igr_exit_logit))

    @property
    def p_loop_cds(self) -> float:
        return float(1.0 - torch.sigmoid(self.cds_exit_logit))

    # ─── log transition matrix ─────────────────────────────────────────

    def log_transitions(self) -> torch.Tensor:
        """Return (S, S) log-prob transition matrix."""
        S = self.NUM_STATES
        dev = self.igr_exit_logit.device
        dtype = self.igr_exit_logit.dtype
        tr = torch.full((S, S), _NEG_INF, device=dev, dtype=dtype)
        igr_exit = torch.sigmoid(self.igr_exit_logit)
        cds_exit = torch.sigmoid(self.cds_exit_logit)
        tr[self.IGR, self.IGR] = torch.log1p(-igr_exit).clamp_min(_MINUS_LOG)
        tr[self.IGR, self.START0] = torch.log(igr_exit).clamp_min(_MINUS_LOG)
        tr[self.START0, self.START1] = torch.zeros((), device=dev, dtype=dtype)
        tr[self.START1, self.START2] = torch.zeros((), device=dev, dtype=dtype)
        tr[self.START2, self.CDS0] = torch.zeros((), device=dev, dtype=dtype)
        tr[self.CDS0, self.CDS1] = torch.zeros((), device=dev, dtype=dtype)
        tr[self.CDS1, self.CDS2] = torch.zeros((), device=dev, dtype=dtype)
        tr[self.CDS2, self.CDS0] = torch.log1p(-cds_exit).clamp_min(_MINUS_LOG)
        tr[self.CDS2, self.STOP0] = torch.log(cds_exit).clamp_min(_MINUS_LOG)
        self._fill_stop_overlap_transitions(tr)
        return tr

    def _fill_stop_overlap_transitions(self, tr: torch.Tensor) -> None:
        dev = tr.device
        dtype = tr.dtype
        p1 = self._p_overlap_1.to(device=dev, dtype=dtype)
        p4 = self._p_overlap_4.to(device=dev, dtype=dtype)
        p7 = self._p_overlap_7.to(device=dev, dtype=dtype)
        one = torch.ones((), device=dev, dtype=dtype)
        after_z0 = (one - p7).clamp_min(1e-12)
        after_z1 = (one - p7 - p4).clamp_min(1e-12)

        tr[self.STOP0, self.STOP1] = torch.log(after_z0).clamp_min(_MINUS_LOG)
        if float(p7.detach().cpu()) > 0.0:
            tr[self.STOP0, self.START_OVERLAP_7] = torch.log(p7).clamp_min(_MINUS_LOG)

        q4 = (p4 / after_z0).clamp(min=0.0, max=1.0)
        tr[self.STOP1, self.STOP2] = torch.log1p(-q4).clamp_min(_MINUS_LOG)
        if float(p4.detach().cpu()) > 0.0:
            tr[self.STOP1, self.START_OVERLAP_4] = torch.log(q4).clamp_min(_MINUS_LOG)

        q1 = (p1 / after_z1).clamp(min=0.0, max=1.0)
        tr[self.STOP2, self.IGR] = torch.log1p(-q1).clamp_min(_MINUS_LOG)
        if float(p1.detach().cpu()) > 0.0:
            tr[self.STOP2, self.START0] = torch.log(q1).clamp_min(_MINUS_LOG)

        tr[self.START_OVERLAP_4, self.START2] = torch.zeros((), device=dev, dtype=dtype)
        tr[self.START_OVERLAP_7, self.START1] = torch.zeros((), device=dev, dtype=dtype)

    def log_init(self) -> torch.Tensor:
        S = self.NUM_STATES
        dev = self.igr_exit_logit.device
        v = torch.full((S,), _NEG_INF, device=dev, dtype=self.igr_exit_logit.dtype)
        v[self.IGR] = 0.0
        return v

    # ─── log c factor (codon constraints) ──────────────────────────────

    def log_c_table(self) -> torch.Tensor:
        """(S, 65) table of log ``c`` values for each state x triplet id.

        Column index 64 corresponds to "N-containing triplet" and always has
        log_c = 0 (no constraint).
        """
        S = self.NUM_STATES
        dev = self.start_codon_logits.device
        dtype = self.start_codon_logits.dtype
        lc = torch.zeros(S, 65, device=dev, dtype=dtype)

        lc[self.START0] = _log_c_row_start_canonical(
            self.start_codon_logits, self.start_ids, dev, dtype,
        )
        lc[self.START_OVERLAP_4] = lc[self.START0]
        lc[self.START_OVERLAP_7] = lc[self.START0]

        z_log = F.log_softmax(self.stop_codon_logits, dim=-1)
        zt_row = torch.full((65,), _NEG_INF, device=dev, dtype=dtype)
        zt_row[self.stop_ids] = z_log
        zt_row[64] = 0.0
        lc[self.STOP0] = zt_row

        # Internal CDS triplets are a hard biological mask, not a codon
        # likelihood model: allow sense codons and forbid in-frame stops.
        c_row = torch.full((65,), _NEG_INF, device=dev, dtype=dtype)
        c_row[self.sense_ids] = 0.0
        c_row[64] = 0.0
        lc[self.CDS0] = c_row
        return lc

    # ─── log emission ──────────────────────────────────────────────────

    def log_emission(
        self,
        nn_probs: torch.Tensor,       # (..., L, 6)
        triplet_ids: torch.Tensor,    # (..., L) long
    ) -> torch.Tensor:
        """Return log emission (..., L, S) = log_b + log_c."""
        K = 6
        alpha = self.alpha
        p_ch = nn_probs.index_select(dim=-1, index=self.canonical_channels)
        b = p_ch * (1.0 - alpha) + (1.0 - p_ch) * (alpha / (K - 1))
        # Floor matches the HMM's minimum channel probability (alpha / (K-1)).
        log_b = torch.log(b.clamp_min(alpha / (K - 1)))

        log_c_all = self.log_c_table()  # (S, 65)
        tid = triplet_ids.clamp(min=0, max=64)
        # log_c_all.T[tid] has shape (..., L, S)
        log_c = log_c_all.t()[tid]
        return _combine_log_emission(
            log_b, log_c, self.START_STATE_IDS, self.start_emission_scale,
        )

    # ─── forward algorithm ─────────────────────────────────────────────

    def forward_log_alpha(
        self,
        log_emit: torch.Tensor,
        *,
        init_mode: str = "strict",
    ) -> torch.Tensor:
        """Log-space forward recursion. ``log_emit`` may be (L, S) or (B, L, S)."""
        squeeze = False
        if log_emit.dim() == 2:
            log_emit = log_emit.unsqueeze(0)
            squeeze = True
        B, L, S = log_emit.shape
        if init_mode not in {"strict", "permissive"}:
            raise ValueError(f"unknown init_mode: {init_mode}")
        log_trans = self.log_transitions()
        if init_mode == "strict":
            log_init = self.log_init()
        else:
            log_init = torch.zeros(S, device=log_emit.device, dtype=log_emit.dtype)
        log_alpha = torch.empty_like(log_emit)
        log_alpha[:, 0] = log_init.unsqueeze(0) + log_emit[:, 0]
        tr_bcast = log_trans.unsqueeze(0)
        for t in range(1, L):
            prev = log_alpha[:, t - 1].unsqueeze(-1)  # (B, S, 1)
            cur = torch.logsumexp(prev + tr_bcast, dim=-2) + log_emit[:, t]
            log_alpha[:, t] = cur
        return log_alpha.squeeze(0) if squeeze else log_alpha

    def forward_nll(self, log_emit: torch.Tensor) -> torch.Tensor:
        """Mean per-position negative log-likelihood under the forward
        algorithm (marginalized over all paths)."""
        log_alpha = self.forward_log_alpha(log_emit)
        if log_alpha.dim() == 2:
            total = torch.logsumexp(log_alpha[-1], dim=-1)
            return -total / log_alpha.shape[0]
        total = torch.logsumexp(log_alpha[:, -1], dim=-1)  # (B,)
        return -total.mean() / log_alpha.shape[1]

    def forward_backward(
        self,
        log_emit: torch.Tensor,
        *,
        init_mode: str = "strict",
    ) -> Tuple[torch.Tensor, torch.Tensor, torch.Tensor, torch.Tensor]:
        """Return differentiable posterior marginals for a strand HMM.

        Parameters
        ----------
        log_emit:
            ``(L, S)`` or ``(B, L, S)`` log emissions from ``log_emission``.
        init_mode:
            ``strict`` starts in IGR; ``permissive`` allows any initial state.

        Returns
        -------
        gamma, log_z, log_alpha, log_beta:
            ``gamma`` has shape ``(B, L, S)`` and rows sum to one.
        """
        if init_mode not in {"strict", "permissive"}:
            raise ValueError(f"unknown init_mode: {init_mode}")
        S = log_emit.shape[-1]
        if init_mode == "strict":
            log_init = self.log_init()
        else:
            log_init = torch.zeros(S, device=log_emit.device, dtype=log_emit.dtype)
        return _forward_backward_log_emit(log_emit, self.log_transitions(), log_init)

    def supervised_nll(
        self,
        log_emit: torch.Tensor,      # (B, L, S)
        true_states: torch.Tensor,   # (B, L) long
    ) -> torch.Tensor:
        """Constrained-path NLL along a known state sequence (preferred when
        GFF-derived state labels are available)."""
        squeeze = False
        if log_emit.dim() == 2:
            log_emit = log_emit.unsqueeze(0)
            true_states = true_states.unsqueeze(0)
            squeeze = True
        B, L, S = log_emit.shape
        log_trans = self.log_transitions()

        emit_path = log_emit.gather(-1, true_states.unsqueeze(-1)).squeeze(-1)
        # Hard codon constraints can disagree with reference-derived labels
        # (rare noncanonical starts, ambiguous sequence, or boundary mismatch).
        # For supervised parameter fitting, ignore those impossible emission
        # terms instead of letting -1e30 dominate the whole epoch loss.
        valid_emit = emit_path > (_NEG_INF / 10)
        emit_path = torch.where(valid_emit, emit_path, torch.zeros_like(emit_path))
        prev_y = true_states[:, :-1]
        next_y = true_states[:, 1:]
        trans_path = log_trans[prev_y, next_y]
        # Some windows can still contain a small number of label transitions
        # that are invalid under the strict HMM graph. Do not let -1e30 terms
        # dominate the loss; ignore those transition contributions.
        valid_trans = trans_path > (_NEG_INF / 10)
        trans_path = torch.where(valid_trans, trans_path, torch.zeros_like(trans_path))
        # Training windows are arbitrary slices and often begin inside a gene.
        # Do not apply the inference-time IGR-only initial prior here; otherwise
        # every non-IGR window start contributes a huge constant -inf-like loss.
        init_path = torch.zeros((B,), device=log_emit.device, dtype=log_emit.dtype)

        total = init_path + emit_path.sum(-1) + trans_path.sum(-1)
        out = -total.mean() / L
        return out

    def true_path_score(
        self,
        log_emit: torch.Tensor,
        true_states: torch.Tensor,
        *,
        init_mode: str = "strict",
        mask_invalid: bool = False,
    ) -> torch.Tensor:
        """Score a known state path under the HMM.

        Parameters
        ----------
        log_emit:
            Log emissions with shape ``(B, L, S)`` or ``(L, S)``.
        true_states:
            Integer path labels with shape ``(B, L)`` or ``(L,)``.
        init_mode:
            ``"strict"`` uses the inference prior (only IGR can start).
            ``"permissive"`` assigns zero initial cost to every state, which is
            useful for arbitrary training windows that may begin inside a gene.
        mask_invalid:
            If true, impossible emission/transition/init terms are ignored
            instead of dominating the score. Keep false for the exact CRF loss.
        """
        if log_emit.dim() == 2:
            log_emit = log_emit.unsqueeze(0)
            true_states = true_states.unsqueeze(0)
        B, L, _ = log_emit.shape
        if init_mode not in {"strict", "permissive"}:
            raise ValueError(f"unknown init_mode: {init_mode}")

        log_trans = self.log_transitions()
        emit_path = log_emit.gather(-1, true_states.unsqueeze(-1)).squeeze(-1)
        trans_path = log_trans[true_states[:, :-1], true_states[:, 1:]]
        if init_mode == "strict":
            init_path = self.log_init()[true_states[:, 0]]
        else:
            init_path = torch.zeros((B,), device=log_emit.device, dtype=log_emit.dtype)

        if mask_invalid:
            emit_path = torch.where(
                emit_path > (_NEG_INF / 10),
                emit_path,
                torch.zeros_like(emit_path),
            )
            trans_path = torch.where(
                trans_path > (_NEG_INF / 10),
                trans_path,
                torch.zeros_like(trans_path),
            )
            init_path = torch.where(
                init_path > (_NEG_INF / 10),
                init_path,
                torch.zeros_like(init_path),
            )
        return init_path + emit_path.sum(-1) + trans_path.sum(-1)

    def crf_supervised_nll(
        self,
        log_emit: torch.Tensor,
        true_states: torch.Tensor,
        *,
        init_mode: str = "strict",
        mask_invalid: bool = False,
    ) -> torch.Tensor:
        """Linear-chain CRF NLL: ``(logZ - true_path_score) / L``.

        This directly trains the reference path to outrank all alternative HMM
        paths. It is the v2 loss used for Phase 2/3 experiments.
        """
        if log_emit.dim() == 2:
            log_emit = log_emit.unsqueeze(0)
            true_states = true_states.unsqueeze(0)
        L = log_emit.shape[1]
        log_alpha = self.forward_log_alpha(log_emit, init_mode=init_mode)
        log_z = torch.logsumexp(log_alpha[:, -1], dim=-1)
        path = self.true_path_score(
            log_emit,
            true_states,
            init_mode=init_mode,
            mask_invalid=mask_invalid,
        )
        return (log_z - path).mean() / L

    # ─── Viterbi ───────────────────────────────────────────────────────

    @torch.no_grad()
    def viterbi_numpy(self, log_emit: np.ndarray) -> np.ndarray:
        """Numpy Viterbi on (L, S) log emissions. Returns (L,) int32 path."""
        log_trans = self.log_transitions().detach().cpu().numpy().astype(np.float64)
        log_init = self.log_init().detach().cpu().numpy().astype(np.float64)
        log_emit = np.asarray(log_emit, dtype=np.float64)
        L, S = log_emit.shape
        delta = log_init + log_emit[0]
        back = np.zeros((L, S), dtype=np.int32)
        for t in range(1, L):
            combined = delta[:, None] + log_trans  # (S_prev, S_next)
            back[t] = combined.argmax(axis=0)
            delta = combined.max(axis=0) + log_emit[t]
        path = np.zeros(L, dtype=np.int32)
        path[-1] = int(delta.argmax())
        for t in range(L - 1, 0, -1):
            path[t - 1] = back[t, path[t]]
        return path


# ─────────────────────────────────────────────────────────────────────────────
# Two-state IGR strand HMM (decode-time topology; Strategy A)
# ─────────────────────────────────────────────────────────────────────────────

DEFAULT_IGR_FIT_JSON = Path("results/igr_analysis/igr_fit.json")
DEFAULT_OVERLAP_TOTAL = 0.156
_IGR_FIT_SCRIPT_HINT = (
    "Run tools/fit_igr_mixture.py to produce igr_fit.json "
    "(e.g. --output-dir results/igr_analysis)."
)


def load_overlap_transition_probs(
    fit_json: Optional[Union[str, Path]] = None,
    *,
    p_overlap_1: Optional[float] = None,
    p_overlap_4: Optional[float] = None,
    p_overlap_7: Optional[float] = None,
    no_overlap: bool = False,
) -> Dict[str, float]:
    """Return unconditional overlap branch probabilities at gene boundaries.

    ``igr_fit.json`` may provide ``pi_overlap_of_total``. If absent, use the
    empirical E. coli-pool default and split overlap depths as 30/55/15.
    Explicit per-depth overrides replace the corresponding split values.
    """
    if no_overlap:
        return {"p_overlap_1": 0.0, "p_overlap_4": 0.0, "p_overlap_7": 0.0}

    path = Path(fit_json) if fit_json is not None else DEFAULT_IGR_FIT_JSON
    fit: Dict[str, Any] = {}
    if path.is_file():
        fit = json.loads(path.read_text())
    total = float(fit.get("pi_overlap_of_total", DEFAULT_OVERLAP_TOTAL))
    p1 = total * 0.30 if p_overlap_1 is None else float(p_overlap_1)
    p4 = total * 0.55 if p_overlap_4 is None else float(p_overlap_4)
    p7 = total * 0.15 if p_overlap_7 is None else float(p_overlap_7)
    for name, val in (("p_overlap_1", p1), ("p_overlap_4", p4), ("p_overlap_7", p7)):
        if not (0.0 <= val <= 1.0):
            raise ValueError(f"{name} must be in [0, 1], got {val}")
    total = p1 + p4 + p7
    if total > 1.0 + 1e-12:
        raise ValueError(f"overlap probabilities sum to {total}, must be <= 1")
    return {"p_overlap_1": p1, "p_overlap_4": p4, "p_overlap_7": p7}


def load_igr_two_state_params(
    fit_json: Optional[Union[str, Path]] = None,
    *,
    pi_short: Optional[float] = None,
    mean_short: Optional[float] = None,
    mean_long: Optional[float] = None,
) -> Dict[str, float]:
    """Load branch / duration parameters for the two-state IGR topology.

    Reads ``pi_short``, ``pi_long``, ``implied_mean_short_bp``, and
    ``implied_mean_long_bp`` from ``igr_fit.json`` unless overridden via CLI.
    """
    path = Path(fit_json) if fit_json is not None else DEFAULT_IGR_FIT_JSON
    fit: Dict[str, Any] = {}
    if path.is_file():
        fit = json.loads(path.read_text())
    elif any(v is None for v in (pi_short, mean_short, mean_long)):
        raise FileNotFoundError(
            f"IGR fit JSON not found: {path.resolve()}\n{_IGR_FIT_SCRIPT_HINT}",
        )

    def _pick(keys: Tuple[str, ...], default: float = float("nan")) -> float:
        for k in keys:
            if k in fit:
                return float(fit[k])
        return default

    pi_s = float(pi_short) if pi_short is not None else _pick(
        ("pi_short", "pi_short_of_positive"),
    )
    mean_s = float(mean_short) if mean_short is not None else _pick(
        ("implied_mean_short_bp",),
    )
    mean_l = float(mean_long) if mean_long is not None else _pick(
        ("implied_mean_long_bp",),
    )
    if not (0.0 <= pi_s <= 1.0):
        raise ValueError(f"pi_short must be in [0, 1], got {pi_s}")
    for name, val in (("mean_short", mean_s), ("mean_long", mean_l)):
        if not (val > 0.0):
            raise ValueError(f"{name} must be positive, got {val}")
    pi_l = 1.0 - pi_s
    return {
        "pi_short": pi_s,
        "pi_long": pi_l,
        "mean_short": mean_s,
        "mean_long": mean_l,
    }


def build_strand_hmm(
    stats: Dict,
    *,
    igr_topology: str = "single",
    igr_fit_json: Optional[Union[str, Path]] = None,
    igr_pi_short: Optional[float] = None,
    igr_mean_short: Optional[float] = None,
    igr_mean_long: Optional[float] = None,
    alpha: float = 0.01,
    trainable: bool = False,
    start_emission_scale: float = 1.0,
    overlap_probs: Optional[Dict[str, float]] = None,
) -> nn.Module:
    """Factory for Strategy-A per-strand HMMs (single or two-state IGR)."""
    topo = (igr_topology or "single").strip().lower()
    if topo == "single":
        return ProkaryoticStrandHMM(
            stats,
            alpha=alpha,
            trainable=trainable,
            start_emission_scale=start_emission_scale,
            overlap_probs=overlap_probs,
        )
    if topo == "two_state":
        params = load_igr_two_state_params(
            igr_fit_json,
            pi_short=igr_pi_short,
            mean_short=igr_mean_short,
            mean_long=igr_mean_long,
        )
        return ProkaryoticStrandHMMTwoStateIGR(
            stats,
            igr_params=params,
            alpha=alpha,
            trainable=trainable,
            start_emission_scale=start_emission_scale,
            overlap_probs=overlap_probs,
        )
    raise ValueError(f"unknown igr_topology: {igr_topology!r} (use 'single' or 'two_state')")


class ProkaryoticStrandHMMTwoStateIGR(ProkaryoticStrandHMM):
    """Single-strand HMM with IGR_short + IGR_long (Strategy A decode)."""

    NUM_STATES = 13
    IGR_SHORT = 0
    IGR_LONG = 1
    IGR_STATES = (IGR_SHORT, IGR_LONG)
    START0, START1, START2 = 2, 3, 4
    CDS0, CDS1, CDS2 = 5, 6, 7
    STOP0, STOP1, STOP2 = 8, 9, 10
    START_OVERLAP_4, START_OVERLAP_7 = 11, 12
    START_STATE_IDS = (START0, START1, START2, START_OVERLAP_4, START_OVERLAP_7)
    STATE_NAMES = (
        "IGR_short", "IGR_long",
        "START0", "START1", "START2",
        "CDS0", "CDS1", "CDS2", "STOP0", "STOP1", "STOP2",
        "START_OVERLAP_4", "START_OVERLAP_7",
    )
    CANONICAL_CHANNELS_TRIPLE = (0, 0, 4, 4, 4, 1, 2, 3, 5, 5, 5, 4, 4)
    CANONICAL_CHANNELS_EDGE = (0, 0, 4, 2, 3, 1, 2, 3, 1, 2, 5, 4, 4)

    def __init__(
        self,
        stats: Dict,
        *,
        igr_params: Dict[str, float],
        alpha: float = 0.01,
        trainable: bool = False,
        start_emission_scale: float = 1.0,
        overlap_probs: Optional[Dict[str, float]] = None,
    ):
        super().__init__(
            stats,
            alpha=alpha,
            trainable=trainable,
            start_emission_scale=start_emission_scale,
            overlap_probs=overlap_probs,
        )
        pi_short = float(igr_params["pi_short"])
        pi_long = float(igr_params["pi_long"])
        mean_short = float(igr_params["mean_short"])
        mean_long = float(igr_params["mean_long"])
        if abs(pi_short + pi_long - 1.0) > 1e-9:
            raise ValueError(f"pi_short + pi_long must equal 1.0, got {pi_short + pi_long}")
        self.register_buffer(
            "_pi_short",
            torch.tensor(pi_short, dtype=torch.float32),
            persistent=False,
        )
        self.register_buffer(
            "_pi_long",
            torch.tensor(pi_long, dtype=torch.float32),
            persistent=False,
        )
        self.register_buffer(
            "_p_exit_igr_short",
            torch.tensor(1.0 / mean_short, dtype=torch.float32),
            persistent=False,
        )
        self.register_buffer(
            "_p_exit_igr_long",
            torch.tensor(1.0 / mean_long, dtype=torch.float32),
            persistent=False,
        )
        mode = get_boundary_label_mode().strip().lower()
        if mode == "triple":
            ch_map = self.CANONICAL_CHANNELS_TRIPLE
        elif mode == "edge":
            ch_map = self.CANONICAL_CHANNELS_EDGE
        else:
            raise ValueError(f"unknown boundary label mode: {mode!r}")
        self.register_buffer(
            "canonical_channels",
            torch.tensor(ch_map, dtype=torch.long),
            persistent=False,
        )
        print("[HMM] IGR topology = two_state")
        print(f"[HMM] pi_short={pi_short:.3f}, pi_long={pi_long:.3f}")
        print(
            f"[HMM] mean_short={mean_short:.1f} bp, mean_long={mean_long:.1f} bp",
        )

    def log_transitions(self) -> torch.Tensor:
        S = self.NUM_STATES
        dev = self.igr_exit_logit.device
        dtype = self.igr_exit_logit.dtype
        tr = torch.full((S, S), _NEG_INF, device=dev, dtype=dtype)

        p_exit_s = self._p_exit_igr_short.to(device=dev, dtype=dtype)
        p_exit_l = self._p_exit_igr_long.to(device=dev, dtype=dtype)
        pi_s = self._pi_short.to(device=dev, dtype=dtype)
        pi_l = self._pi_long.to(device=dev, dtype=dtype)
        cds_exit = torch.sigmoid(self.cds_exit_logit)

        tr[self.IGR_SHORT, self.IGR_SHORT] = torch.log1p(-p_exit_s).clamp_min(_MINUS_LOG)
        tr[self.IGR_SHORT, self.START0] = torch.log(p_exit_s).clamp_min(_MINUS_LOG)
        tr[self.IGR_LONG, self.IGR_LONG] = torch.log1p(-p_exit_l).clamp_min(_MINUS_LOG)
        tr[self.IGR_LONG, self.START0] = torch.log(p_exit_l).clamp_min(_MINUS_LOG)

        tr[self.START0, self.START1] = torch.zeros((), device=dev, dtype=dtype)
        tr[self.START1, self.START2] = torch.zeros((), device=dev, dtype=dtype)
        tr[self.START2, self.CDS0] = torch.zeros((), device=dev, dtype=dtype)
        tr[self.CDS0, self.CDS1] = torch.zeros((), device=dev, dtype=dtype)
        tr[self.CDS1, self.CDS2] = torch.zeros((), device=dev, dtype=dtype)
        tr[self.CDS2, self.CDS0] = torch.log1p(-cds_exit).clamp_min(_MINUS_LOG)
        tr[self.CDS2, self.STOP0] = torch.log(cds_exit).clamp_min(_MINUS_LOG)
        self._fill_stop_overlap_transitions(tr)
        p1 = self._p_overlap_1.to(device=dev, dtype=dtype)
        p4 = self._p_overlap_4.to(device=dev, dtype=dtype)
        p7 = self._p_overlap_7.to(device=dev, dtype=dtype)
        after_z1 = (torch.ones((), device=dev, dtype=dtype) - p7 - p4).clamp_min(1e-12)
        q1 = (p1 / after_z1).clamp(min=0.0, max=1.0)
        through = torch.log1p(-q1).clamp_min(_MINUS_LOG)
        tr[self.STOP2, self.IGR_SHORT] = through + torch.log(pi_s).clamp_min(_MINUS_LOG)
        tr[self.STOP2, self.IGR_LONG] = through + torch.log(pi_l).clamp_min(_MINUS_LOG)
        return tr

    def log_init(self) -> torch.Tensor:
        S = self.NUM_STATES
        dev = self.igr_exit_logit.device
        dtype = self.igr_exit_logit.dtype
        v = torch.full((S,), _NEG_INF, device=dev, dtype=dtype)
        pi_s = self._pi_short.to(device=dev, dtype=dtype)
        pi_l = self._pi_long.to(device=dev, dtype=dtype)
        v[self.IGR_SHORT] = torch.log(pi_s).clamp_min(_MINUS_LOG)
        v[self.IGR_LONG] = torch.log(pi_l).clamp_min(_MINUS_LOG)
        return v


# ─────────────────────────────────────────────────────────────────────────────
# Joint HMM (19 states)
# ─────────────────────────────────────────────────────────────────────────────


class ProkaryoticJointHMM(nn.Module):
    """Joint HMM over both strands (Strategy B).

    Consumes the full 11-channel NN prediction directly; the − strand branch
    reads − strand frame / START / STOP channels and looks up reverse-complement
    triplets from the forward sequence.
    """

    NUM_STATES = 23
    STATE_NAMES = (
        "IGR",
        "START0+", "START1+", "START2+", "CDS0+", "CDS1+", "CDS2+",
        "STOP0+", "STOP1+", "STOP2+",
        "START0-", "START1-", "START2-", "CDS0-", "CDS1-", "CDS2-",
        "STOP0-", "STOP1-", "STOP2-",
        "START_OVERLAP_4+", "START_OVERLAP_7+",
        "START_OVERLAP_4-", "START_OVERLAP_7-",
    )
    IGR = 0
    S0P, S1P, S2P, C0P, C1P, C2P, Z0P, Z1P, Z2P = range(1, 10)
    S0M, S1M, S2M, C0M, C1M, C2M, Z0M, Z1M, Z2M = range(10, 19)
    O4P, O7P, O4M, O7M = range(19, 23)

    # Canonical channel (into 11-dim merged multi-label NN probs).
    # The - branch is traversed in forward genomic order (biological 3'->5'),
    # so its CDS state cycle is reversed relative to the forward-coordinate
    # frame labels: C0- emits F2-, C1- emits F1-, C2- emits F0-.
    NN_CHANNEL_TRIPLE = (
        0,                                   # IGR
        7, 7, 7, 1, 2, 3, 9, 9, 9,            # + branch
        8, 8, 8, 6, 5, 4, 10, 10, 10,         # - branch
        7, 7, 8, 8,                            # overlap START0-like states
    )
    NN_CHANNEL_EDGE = (
        0,                                    # IGR
        7, 2, 3, 1, 2, 3, 1, 2, 9,             # + branch
        8, 5, 6, 6, 5, 4, 4, 5, 10,            # - branch
        7, 7, 8, 8,                             # overlap START0-like states
    )

    START_STATE_IDS = (1, 2, 3, 10, 11, 12, 19, 20, 21, 22)

    def __init__(
        self,
        stats: Dict,
        alpha: float = 0.01,
        trainable: bool = False,
        start_emission_scale: float = 1.0,
        overlap_probs: Optional[Dict[str, float]] = None,
    ):
        super().__init__()
        self.alpha = float(alpha)
        self.start_emission_scale = float(start_emission_scale)
        overlap_probs = overlap_probs or load_overlap_transition_probs()
        d = stats["derived"]

        self.igr_exit_logit = nn.Parameter(
            torch.tensor(_prob_to_logit(d["p_exit_igr"]), dtype=torch.float32),
            requires_grad=trainable,
        )
        self.cds_exit_logit_plus = nn.Parameter(
            torch.tensor(_prob_to_logit(d["p_exit_cds"]), dtype=torch.float32),
            requires_grad=trainable,
        )
        self.cds_exit_logit_minus = nn.Parameter(
            torch.tensor(_prob_to_logit(d["p_exit_cds"]), dtype=torch.float32),
            requires_grad=trainable,
        )
        sfreqs = stats.get("start_codon_freqs") or ECOLI_START_CODON_FREQS
        s_init = torch.tensor(
            [max(sfreqs.get(c, 0.0), 1e-6) for c in START_CODONS_10],
            dtype=torch.float32,
        )
        self.start_codon_logits_plus = nn.Parameter(
            torch.log(s_init.clone()), requires_grad=trainable,
        )
        self.start_codon_logits_minus = nn.Parameter(
            torch.log(s_init.clone()), requires_grad=trainable,
        )
        zfreqs = stats.get("stop_codon_freqs") or ECOLI_STOP_CODON_FREQS
        z_init = torch.tensor(
            [max(zfreqs.get(c, 0.0), 1e-6) for c in STOP_CODONS],
            dtype=torch.float32,
        )
        self.stop_codon_logits_plus = nn.Parameter(
            torch.log(z_init.clone()), requires_grad=trainable,
        )
        self.stop_codon_logits_minus = nn.Parameter(
            torch.log(z_init.clone()), requires_grad=trainable,
        )

        self.register_buffer(
            "start_ids",
            torch.tensor([codon_to_id(c) for c in START_CODONS_10], dtype=torch.long),
        )
        self.register_buffer(
            "stop_ids",
            torch.tensor([codon_to_id(c) for c in STOP_CODONS], dtype=torch.long),
        )
        self.register_buffer(
            "sense_ids",
            torch.tensor(
                sorted(set(range(64)) - set([codon_to_id(c) for c in STOP_CODONS])),
                dtype=torch.long,
            ),
        )
        self.register_buffer(
            "nn_channel", torch.tensor(joint_hmm_nn_channels(), dtype=torch.long),
            persistent=False,
        )
        minus_states = torch.zeros(self.NUM_STATES, dtype=torch.bool)
        minus_states[10:] = True
        minus_states[self.O4P] = False
        minus_states[self.O7P] = False
        self.register_buffer("is_minus_state", minus_states, persistent=False)
        self.register_buffer(
            "_p_overlap_1",
            torch.tensor(float(overlap_probs["p_overlap_1"]), dtype=torch.float32),
            persistent=False,
        )
        self.register_buffer(
            "_p_overlap_4",
            torch.tensor(float(overlap_probs["p_overlap_4"]), dtype=torch.float32),
            persistent=False,
        )
        self.register_buffer(
            "_p_overlap_7",
            torch.tensor(float(overlap_probs["p_overlap_7"]), dtype=torch.float32),
            persistent=False,
        )

    # ─── log transitions ───────────────────────────────────────────────

    def log_transitions(self) -> torch.Tensor:
        S = self.NUM_STATES
        dev = self.igr_exit_logit.device
        dtype = self.igr_exit_logit.dtype
        tr = torch.full((S, S), _NEG_INF, device=dev, dtype=dtype)

        igr_exit = torch.sigmoid(self.igr_exit_logit)
        # Split evenly between + and - strand initiation
        log_half = torch.log(torch.tensor(0.5, device=dev, dtype=dtype))
        tr[self.IGR, self.IGR] = torch.log1p(-igr_exit).clamp_min(_MINUS_LOG)
        log_exit = torch.log(igr_exit).clamp_min(_MINUS_LOG)
        tr[self.IGR, self.S0P] = log_exit + log_half
        tr[self.IGR, self.Z2M] = log_exit + log_half

        # + branch (same orientation as strand HMM)
        tr[self.S0P, self.S1P] = 0.0
        tr[self.S1P, self.S2P] = 0.0
        tr[self.S2P, self.C0P] = 0.0
        tr[self.C0P, self.C1P] = 0.0
        tr[self.C1P, self.C2P] = 0.0
        cds_exit_p = torch.sigmoid(self.cds_exit_logit_plus)
        tr[self.C2P, self.C0P] = torch.log1p(-cds_exit_p).clamp_min(_MINUS_LOG)
        tr[self.C2P, self.Z0P] = torch.log(cds_exit_p).clamp_min(_MINUS_LOG)
        self._fill_plus_overlap_transitions(tr)

        # - branch: traversed in forward-coordinate order, which is biological
        # 3'→5'. That reverses the edge order but keeps the same length prior.
        tr[self.Z2M, self.Z1M] = 0.0
        tr[self.Z1M, self.Z0M] = 0.0
        tr[self.Z0M, self.C2M] = 0.0
        tr[self.C2M, self.C1M] = 0.0
        tr[self.C1M, self.C0M] = 0.0
        cds_exit_m = torch.sigmoid(self.cds_exit_logit_minus)
        tr[self.C0M, self.C2M] = torch.log1p(-cds_exit_m).clamp_min(_MINUS_LOG)
        tr[self.C0M, self.S2M] = torch.log(cds_exit_m).clamp_min(_MINUS_LOG)
        self._fill_minus_overlap_transitions(tr)
        return tr

    def _overlap_conditionals(self, dev: torch.device, dtype: torch.dtype) -> Tuple[torch.Tensor, torch.Tensor, torch.Tensor]:
        p1 = self._p_overlap_1.to(device=dev, dtype=dtype)
        p4 = self._p_overlap_4.to(device=dev, dtype=dtype)
        p7 = self._p_overlap_7.to(device=dev, dtype=dtype)
        one = torch.ones((), device=dev, dtype=dtype)
        after_0 = (one - p7).clamp_min(1e-12)
        after_1 = (one - p7 - p4).clamp_min(1e-12)
        q4 = (p4 / after_0).clamp(min=0.0, max=1.0)
        q1 = (p1 / after_1).clamp(min=0.0, max=1.0)
        return p7, q4, q1

    def _fill_plus_overlap_transitions(self, tr: torch.Tensor) -> None:
        dev = tr.device
        dtype = tr.dtype
        p7, q4, q1 = self._overlap_conditionals(dev, dtype)
        tr[self.Z0P, self.Z1P] = torch.log1p(-p7).clamp_min(_MINUS_LOG)
        if float(p7.detach().cpu()) > 0.0:
            tr[self.Z0P, self.O7P] = torch.log(p7).clamp_min(_MINUS_LOG)
        tr[self.Z1P, self.Z2P] = torch.log1p(-q4).clamp_min(_MINUS_LOG)
        if float(q4.detach().cpu()) > 0.0:
            tr[self.Z1P, self.O4P] = torch.log(q4).clamp_min(_MINUS_LOG)
        tr[self.Z2P, self.IGR] = torch.log1p(-q1).clamp_min(_MINUS_LOG)
        if float(q1.detach().cpu()) > 0.0:
            tr[self.Z2P, self.S0P] = torch.log(q1).clamp_min(_MINUS_LOG)
        tr[self.O4P, self.S2P] = torch.zeros((), device=dev, dtype=dtype)
        tr[self.O7P, self.S1P] = torch.zeros((), device=dev, dtype=dtype)

    def _fill_minus_overlap_transitions(self, tr: torch.Tensor) -> None:
        dev = tr.device
        dtype = tr.dtype
        p7, q4, q1 = self._overlap_conditionals(dev, dtype)
        tr[self.S2M, self.S1M] = torch.log1p(-p7).clamp_min(_MINUS_LOG)
        if float(p7.detach().cpu()) > 0.0:
            tr[self.S2M, self.O7M] = torch.log(p7).clamp_min(_MINUS_LOG)
        tr[self.S1M, self.S0M] = torch.log1p(-q4).clamp_min(_MINUS_LOG)
        if float(q4.detach().cpu()) > 0.0:
            tr[self.S1M, self.O4M] = torch.log(q4).clamp_min(_MINUS_LOG)
        tr[self.S0M, self.IGR] = torch.log1p(-q1).clamp_min(_MINUS_LOG)
        if float(q1.detach().cpu()) > 0.0:
            tr[self.S0M, self.Z2M] = torch.log(q1).clamp_min(_MINUS_LOG)
        tr[self.O4M, self.Z0M] = torch.zeros((), device=dev, dtype=dtype)
        tr[self.O7M, self.Z1M] = torch.zeros((), device=dev, dtype=dtype)

    def log_init(self) -> torch.Tensor:
        S = self.NUM_STATES
        dev = self.igr_exit_logit.device
        v = torch.full((S,), _NEG_INF, device=dev, dtype=self.igr_exit_logit.dtype)
        v[self.IGR] = 0.0
        return v

    # ─── log c tables ─────────────────────────────────────────────────

    def log_c_table(self) -> torch.Tensor:
        """(S, 65). Column 64 = uniform on N-containing triplets."""
        S = self.NUM_STATES
        dev = self.start_codon_logits_plus.device
        dtype = self.start_codon_logits_plus.dtype
        lc = torch.zeros(S, 65, device=dev, dtype=dtype)

        def _codon_row(logits: torch.Tensor, ids: torch.Tensor) -> torch.Tensor:
            row = torch.full((65,), _NEG_INF, device=dev, dtype=dtype)
            row[ids] = F.log_softmax(logits, dim=-1)
            row[64] = 0.0
            return row

        def _sense_row() -> torch.Tensor:
            row = torch.full((65,), _NEG_INF, device=dev, dtype=dtype)
            # Internal CDS triplets are a hard biological mask, not a codon
            # likelihood model: allow sense codons and forbid in-frame stops.
            row[self.sense_ids] = 0.0
            row[64] = 0.0
            return row

        lc[self.S0P] = _log_c_row_start_canonical(
            self.start_codon_logits_plus, self.start_ids, dev, dtype,
        )
        lc[self.O4P] = lc[self.S0P]
        lc[self.O7P] = lc[self.S0P]
        lc[self.C0P] = _sense_row()
        lc[self.Z0P] = _codon_row(self.stop_codon_logits_plus, self.stop_ids)
        lc[self.S0M] = _log_c_row_start_canonical(
            self.start_codon_logits_minus, self.start_ids, dev, dtype,
        )
        lc[self.O4M] = lc[self.S0M]
        lc[self.O7M] = lc[self.S0M]
        lc[self.C0M] = _sense_row()
        lc[self.Z0M] = _codon_row(self.stop_codon_logits_minus, self.stop_ids)
        return lc

    # ─── log emission ──────────────────────────────────────────────────

    def log_emission(
        self,
        nn_probs: torch.Tensor,         # (..., L, 11)
        triplet_plus: torch.Tensor,     # (..., L) long
        triplet_minus: torch.Tensor,    # (..., L) long
    ) -> torch.Tensor:
        """Return log emission (..., L, S)."""
        K = 11
        alpha = self.alpha
        p_ch = nn_probs.index_select(dim=-1, index=self.nn_channel)  # (..., L, S)
        b = p_ch * (1.0 - alpha) + (1.0 - p_ch) * (alpha / (K - 1))
        log_b = torch.log(b.clamp_min(1e-12))

        log_c_all = self.log_c_table()  # (S, 65)
        tp = triplet_plus.clamp(min=0, max=64)
        tm = triplet_minus.clamp(min=0, max=64)
        log_c_plus = log_c_all.t()[tp]   # (..., L, S)
        log_c_minus = log_c_all.t()[tm]
        # Select per state
        minus = self.is_minus_state.view(*([1] * (log_c_plus.dim() - 1)), -1)
        log_c = torch.where(minus, log_c_minus, log_c_plus)
        return _combine_log_emission(
            log_b, log_c, self.START_STATE_IDS, self.start_emission_scale,
        )

    # ─── forward / Viterbi ────────────────────────────────────────────

    def forward_log_alpha(
        self,
        log_emit: torch.Tensor,
        *,
        init_mode: str = "strict",
    ) -> torch.Tensor:
        squeeze = False
        if log_emit.dim() == 2:
            log_emit = log_emit.unsqueeze(0)
            squeeze = True
        B, L, S = log_emit.shape
        if init_mode not in {"strict", "permissive"}:
            raise ValueError(f"unknown init_mode: {init_mode}")
        log_trans = self.log_transitions()
        if init_mode == "strict":
            log_init = self.log_init()
        else:
            log_init = torch.zeros(S, device=log_emit.device, dtype=log_emit.dtype)
        log_alpha = torch.empty_like(log_emit)
        log_alpha[:, 0] = log_init.unsqueeze(0) + log_emit[:, 0]
        tr_bcast = log_trans.unsqueeze(0)
        for t in range(1, L):
            prev = log_alpha[:, t - 1].unsqueeze(-1)
            cur = torch.logsumexp(prev + tr_bcast, dim=-2) + log_emit[:, t]
            log_alpha[:, t] = cur
        return log_alpha.squeeze(0) if squeeze else log_alpha

    def forward_nll(self, log_emit: torch.Tensor) -> torch.Tensor:
        log_alpha = self.forward_log_alpha(log_emit)
        if log_alpha.dim() == 2:
            total = torch.logsumexp(log_alpha[-1], dim=-1)
            return -total / log_alpha.shape[0]
        total = torch.logsumexp(log_alpha[:, -1], dim=-1)
        return -total.mean() / log_alpha.shape[1]

    def forward_backward(
        self,
        log_emit: torch.Tensor,
        *,
        init_mode: str = "strict",
    ) -> Tuple[torch.Tensor, torch.Tensor, torch.Tensor, torch.Tensor]:
        """Return differentiable posterior marginals for the joint HMM.

        Shapes mirror ``ProkaryoticStrandHMM.forward_backward``: ``log_emit`` is
        ``(L, 19)`` or ``(B, L, 19)``, ``gamma`` is always ``(B, L, 19)``.
        """
        if init_mode not in {"strict", "permissive"}:
            raise ValueError(f"unknown init_mode: {init_mode}")
        S = log_emit.shape[-1]
        if init_mode == "strict":
            log_init = self.log_init()
        else:
            log_init = torch.zeros(S, device=log_emit.device, dtype=log_emit.dtype)
        return _forward_backward_log_emit(log_emit, self.log_transitions(), log_init)

    def supervised_nll(
        self, log_emit: torch.Tensor, true_states: torch.Tensor,
    ) -> torch.Tensor:
        if log_emit.dim() == 2:
            log_emit = log_emit.unsqueeze(0)
            true_states = true_states.unsqueeze(0)
        B, L, S = log_emit.shape
        log_trans = self.log_transitions()
        emit_path = log_emit.gather(-1, true_states.unsqueeze(-1)).squeeze(-1)
        # Hard codon constraints can disagree with reference-derived labels
        # (rare noncanonical starts, ambiguous sequence, or boundary mismatch).
        # For supervised parameter fitting, ignore those impossible emission
        # terms instead of letting -1e30 dominate the whole epoch loss.
        valid_emit = emit_path > (_NEG_INF / 10)
        emit_path = torch.where(valid_emit, emit_path, torch.zeros_like(emit_path))
        trans_path = log_trans[true_states[:, :-1], true_states[:, 1:]]
        # Ignore residual invalid label transitions to avoid saturated losses.
        valid_trans = trans_path > (_NEG_INF / 10)
        trans_path = torch.where(valid_trans, trans_path, torch.zeros_like(trans_path))
        # Training windows are arbitrary slices and often begin inside a gene.
        # Use a permissive initial state for supervised training; inference still
        # uses ``log_init`` in forward/Viterbi decoding.
        init_path = torch.zeros((B,), device=log_emit.device, dtype=log_emit.dtype)
        total = init_path + emit_path.sum(-1) + trans_path.sum(-1)
        return -total.mean() / L

    def true_path_score(
        self,
        log_emit: torch.Tensor,
        true_states: torch.Tensor,
        *,
        init_mode: str = "strict",
        mask_invalid: bool = False,
    ) -> torch.Tensor:
        """Score a known 19-state path under the joint HMM."""
        if log_emit.dim() == 2:
            log_emit = log_emit.unsqueeze(0)
            true_states = true_states.unsqueeze(0)
        B, L, _ = log_emit.shape
        if init_mode not in {"strict", "permissive"}:
            raise ValueError(f"unknown init_mode: {init_mode}")

        log_trans = self.log_transitions()
        emit_path = log_emit.gather(-1, true_states.unsqueeze(-1)).squeeze(-1)
        trans_path = log_trans[true_states[:, :-1], true_states[:, 1:]]
        if init_mode == "strict":
            init_path = self.log_init()[true_states[:, 0]]
        else:
            init_path = torch.zeros((B,), device=log_emit.device, dtype=log_emit.dtype)

        if mask_invalid:
            emit_path = torch.where(
                emit_path > (_NEG_INF / 10),
                emit_path,
                torch.zeros_like(emit_path),
            )
            trans_path = torch.where(
                trans_path > (_NEG_INF / 10),
                trans_path,
                torch.zeros_like(trans_path),
            )
            init_path = torch.where(
                init_path > (_NEG_INF / 10),
                init_path,
                torch.zeros_like(init_path),
            )
        return init_path + emit_path.sum(-1) + trans_path.sum(-1)

    def crf_supervised_nll(
        self,
        log_emit: torch.Tensor,
        true_states: torch.Tensor,
        *,
        init_mode: str = "strict",
        mask_invalid: bool = False,
    ) -> torch.Tensor:
        """Linear-chain CRF NLL: ``(logZ - true_path_score) / L``."""
        if log_emit.dim() == 2:
            log_emit = log_emit.unsqueeze(0)
            true_states = true_states.unsqueeze(0)
        L = log_emit.shape[1]
        log_alpha = self.forward_log_alpha(log_emit, init_mode=init_mode)
        log_z = torch.logsumexp(log_alpha[:, -1], dim=-1)
        path = self.true_path_score(
            log_emit,
            true_states,
            init_mode=init_mode,
            mask_invalid=mask_invalid,
        )
        return (log_z - path).mean() / L

    @torch.no_grad()
    def viterbi_numpy(self, log_emit: np.ndarray) -> np.ndarray:
        log_trans = self.log_transitions().detach().cpu().numpy().astype(np.float64)
        log_init = self.log_init().detach().cpu().numpy().astype(np.float64)
        log_emit = np.asarray(log_emit, dtype=np.float64)
        L, S = log_emit.shape
        delta = log_init + log_emit[0]
        back = np.zeros((L, S), dtype=np.int32)
        for t in range(1, L):
            combined = delta[:, None] + log_trans
            back[t] = combined.argmax(axis=0)
            delta = combined.max(axis=0) + log_emit[t]
        path = np.zeros(L, dtype=np.int32)
        path[-1] = int(delta.argmax())
        for t in range(L - 1, 0, -1):
            path[t - 1] = back[t, path[t]]
        return path


# ─────────────────────────────────────────────────────────────────────────────
# Helpers for channel slicing
# ─────────────────────────────────────────────────────────────────────────────


def slice_plus_channels(probs11: np.ndarray) -> np.ndarray:
    """Extract the 6-ch + strand slice from merged 11-ch NN probs (L, 11)."""
    return probs11[:, [0, 1, 2, 3, 7, 9]]


def slice_minus_channels(probs11: np.ndarray) -> np.ndarray:
    """Extract the 6-ch − strand slice from merged 11-ch NN probs (L, 11)."""
    return probs11[:, [0, 4, 5, 6, 8, 10]]


def reverse_for_minus_strand(probs_6: np.ndarray) -> np.ndarray:
    """Flip − strand NN slice in time so it aligns with the reverse-complemented
    sequence (used when running a strand HMM on the − strand).

    Forward-coordinate reverse-strand frame labels run in the opposite cycle
    after time reversal, so swap F0/F2 for the strand HMM's CDS0->CDS1->CDS2
    progression in reverse-complement orientation.
    """
    return np.ascontiguousarray(probs_6[::-1][:, [0, 3, 2, 1, 4, 5]])


# ─────────────────────────────────────────────────────────────────────────────
# State-label generation from GFF (for supervised training)
# ─────────────────────────────────────────────────────────────────────────────


def strand_state_labels_from_true_classes(
    class_labels_fwd: np.ndarray,
    seq_len: int,
) -> np.ndarray:
    """Convert a per-position 6-state class label array (as produced by
    ``Annotation.get_full_chromosome_labels`` for one strand) into HMM state
    labels for a ``ProkaryoticStrandHMM``.

    Input labels use the scheme from ``annotation_gtf``:
        0 = IGR, 1/2/3 = CDS frame0/1/2, 4 = START, 5 = STOP.

    Returns (L,) int64 with values in ``[0, 10)``.
    """
    out = np.zeros(seq_len, dtype=np.int64)
    out[:] = ProkaryoticStrandHMM.IGR

    i = 0
    L = seq_len
    FR = {1: 0, 2: 1, 3: 2}
    while i < L:
        c = int(class_labels_fwd[i])
        if c == 4:
            j = i
            while j < L and class_labels_fwd[j] == 4:
                j += 1
            # Assign START0/1/2 across the START-labeled run (typically 3 bases,
            # but can be 1 base in edge-label training mode).
            for k in range(i, min(i + 3, j)):
                out[k] = ProkaryoticStrandHMM.START0 + (k - i)
            for k in range(i + 3, j):
                out[k] = ProkaryoticStrandHMM.CDS0 + ((k - i) % 3)
            i = j
        elif c == 5:
            j = i
            while j < L and class_labels_fwd[j] == 5:
                j += 1
            for k in range(i, min(i + 3, j)):
                out[k] = ProkaryoticStrandHMM.STOP0 + (k - i)
            i = j
        elif c in (1, 2, 3):
            out[i] = ProkaryoticStrandHMM.CDS0 + FR[c]
            i += 1
        else:
            out[i] = ProkaryoticStrandHMM.IGR
            i += 1
    return out


def joint_state_labels_from_merged(
    labels_fwd: np.ndarray,   # (L,) 6-state + strand
    labels_rev: np.ndarray,   # (L,) 6-state - strand, indexed in forward coords
    seq_len: int,
) -> np.ndarray:
    """Generate joint 19-state HMM labels for the joint HMM.

    Overlapping + and − coding regions are resolved by preferring the + strand
    branch (strand dominance is arbitrary; the joint HMM forbids dual coding
    by construction, so we cannot label both strands simultaneously).
    """
    out = np.zeros(seq_len, dtype=np.int64)  # default IGR
    plus = strand_state_labels_from_true_classes(labels_fwd, seq_len)

    minus_base = strand_state_labels_from_true_classes(labels_rev[::-1], seq_len)[::-1]
    # minus_base uses strand-HMM indexing (0..9). Within the joint HMM, start/stop
    # labels are reversed in biological orientation:
    #   − strand 5' end (biological START on − strand) sits at HIGH forward pos.
    # strand_state_labels_from_true_classes processed labels_rev[::-1] (so START
    # at biological 5' is at low forward coords). Flipping back via [::-1]
    # restores the + strand-style chain at forward coords, but then we must
    # remap because on the − branch the joint HMM runs the chain in reversed
    # order (IGR → STOP2- → STOP1- → ... → START0- → IGR).
    #
    # We need to translate 10-state indices to 19-state indices:
    #   IGR → IGR (0)
    #   STRAND start block (START0/1/2) → joint S0M/S1M/S2M but with reversed
    #   ordering in forward coords.
    mapping = np.zeros(10, dtype=np.int64)
    mapping[ProkaryoticStrandHMM.IGR] = ProkaryoticJointHMM.IGR
    # The strand-state labels for minus (after reverse/flip) still follow the
    # plus-style local order START0->...->STOP2 in forward coordinates. The
    # joint minus branch runs the reverse chain in forward coordinates:
    # IGR->Z2M->Z1M->Z0M->C2M->C1M->C0M->...->S2M->S1M->S0M->IGR.
    # Remap frame/start/stop indices accordingly.
    mapping[ProkaryoticStrandHMM.START0] = ProkaryoticJointHMM.S2M
    mapping[ProkaryoticStrandHMM.START1] = ProkaryoticJointHMM.S1M
    mapping[ProkaryoticStrandHMM.START2] = ProkaryoticJointHMM.S0M
    mapping[ProkaryoticStrandHMM.CDS0] = ProkaryoticJointHMM.C2M
    mapping[ProkaryoticStrandHMM.CDS1] = ProkaryoticJointHMM.C1M
    mapping[ProkaryoticStrandHMM.CDS2] = ProkaryoticJointHMM.C0M
    mapping[ProkaryoticStrandHMM.STOP0] = ProkaryoticJointHMM.Z2M
    mapping[ProkaryoticStrandHMM.STOP1] = ProkaryoticJointHMM.Z1M
    mapping[ProkaryoticStrandHMM.STOP2] = ProkaryoticJointHMM.Z0M

    # Convert plus states to joint indices:
    plus_map = np.zeros(10, dtype=np.int64)
    plus_map[ProkaryoticStrandHMM.IGR] = ProkaryoticJointHMM.IGR
    plus_map[ProkaryoticStrandHMM.START0] = ProkaryoticJointHMM.S0P
    plus_map[ProkaryoticStrandHMM.START1] = ProkaryoticJointHMM.S1P
    plus_map[ProkaryoticStrandHMM.START2] = ProkaryoticJointHMM.S2P
    plus_map[ProkaryoticStrandHMM.CDS0] = ProkaryoticJointHMM.C0P
    plus_map[ProkaryoticStrandHMM.CDS1] = ProkaryoticJointHMM.C1P
    plus_map[ProkaryoticStrandHMM.CDS2] = ProkaryoticJointHMM.C2P
    plus_map[ProkaryoticStrandHMM.STOP0] = ProkaryoticJointHMM.Z0P
    plus_map[ProkaryoticStrandHMM.STOP1] = ProkaryoticJointHMM.Z1P
    plus_map[ProkaryoticStrandHMM.STOP2] = ProkaryoticJointHMM.Z2P

    plus_j = plus_map[plus]
    minus_j = mapping[minus_base]
    # Prefer + strand coding where both assign a non-IGR label
    both = (plus_j != 0) & (minus_j != 0)
    out = np.where(plus_j != 0, plus_j, minus_j)
    out[both] = plus_j[both]
    return out
